    Bug 1970022 - Remove references to nsIWebContentHandlerInfo. r=mkmelin

    This interface disappeared in 2018 (bug 1477670). We still have some references which fail in very rare circumstances.

    Differential Revision: https://phabricator.services.mozilla.com/D306660

diff --git a/mail/components/preferences/applicationManager.js b/mail/components/preferences/applicationManager.js
index 72962481664..80589ee9a23 100644
--- a/mail/components/preferences/applicationManager.js
+++ b/mail/components/preferences/applicationManager.js
@@ -100,8 +100,6 @@ var gAppManagerDialog = {
       address = app.executable.path;
     } else if (app instanceof Ci.nsIWebHandlerApp) {
       address = app.uriTemplate;
-    } else if (app instanceof Ci.nsIWebContentHandlerInfo) {
-      address = app.uri;
     }
     document.getElementById("appLocation").value = address;
     var bundle = document.getElementById("appManagerBundle");
diff --git a/mail/components/preferences/general.js b/mail/components/preferences/general.js
index 2a8b2607865..6d28e398405 100644
--- a/mail/components/preferences/general.js
+++ b/mail/components/preferences/general.js
@@ -2026,10 +2026,6 @@ var gGeneralPane = {
       return aHandlerApp.uriTemplate;
     }

-    if (aHandlerApp instanceof Ci.nsIWebContentHandlerInfo) {
-      return aHandlerApp.uri;
-    }
-
     return false;
   },

@@ -2141,10 +2137,6 @@ var gGeneralPane = {
       return this._getIconURLForWebApp(aHandlerApp.uriTemplate);
     }

-    if (aHandlerApp instanceof Ci.nsIWebContentHandlerInfo) {
-      return this._getIconURLForWebApp(aHandlerApp.uri);
-    }
-
     // We know nothing about other kinds of handler apps.
     return "";
   },
